package tests

import (
	"context"
	"errors"
	"net/http"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"engflex-api/internal/modules/lessons/services"
)

// fakeCommandRunner is a minimal local test double for CommandRunner — not
// a repository, so it is written by hand rather than generated by mockery.
type fakeCommandRunner struct {
	gotName string
	gotArgs []string
	output  []byte
	err     error
}

func (f *fakeCommandRunner) CombinedOutput(_ context.Context, name string, args ...string) ([]byte, error) {
	f.gotName, f.gotArgs = name, args
	return f.output, f.err
}

func TestAudioSynthesisService_SynthesizeForActivity(t *testing.T) {
	validID := "44444444-0000-4000-8000-000000000112"

	tests := []struct {
		name       string
		activityID string
		runner     *fakeCommandRunner
		wantErr    bool
		wantStatus int
	}{
		{
			name:       "invalid id: 400, runner never called",
			activityID: "not-a-uuid",
			runner:     &fakeCommandRunner{},
			wantErr:    true,
			wantStatus: http.StatusBadRequest,
		},
		{
			name:       "success: script exits 0",
			activityID: validID,
			runner:     &fakeCommandRunner{output: []byte("uploaded 1 object(s) to lesson-audio")},
		},
		{
			name:       "script failure: 422 with script output as message",
			activityID: validID,
			runner:     &fakeCommandRunner{output: []byte("activity x: not found"), err: errors.New("exit status 1")},
			wantErr:    true,
			wantStatus: http.StatusUnprocessableEntity,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			svc := services.NewAudioSynthesisService(tt.runner)
			err := svc.SynthesizeForActivity(context.Background(), tt.activityID)

			if tt.wantErr {
				requireAppError(t, err, tt.wantStatus)
			} else {
				require.NoError(t, err)
				assert.Equal(t, "uv", tt.runner.gotName)
				assert.Contains(t, tt.runner.gotArgs, "--activity-id="+tt.activityID)
			}
		})
	}
}
